// storeActions returns the actions of the generated sequences of Store
// over the subject that subject returns. The actions of a case take their
// keys from the pools that it draws.
func storeActions(c *prop.Case, subject func() hosted.Store) []stateful.Action[struct{}] {
	keysString := c.Draw(prop.List(prop.Of[string](), prop.Unique(), prop.MinSize(1), prop.MaxSize(3)), "keys.string")
	return []stateful.Action[struct{}]{
		{
			Name: "Put",
			Input: func(c *prop.Case, _ struct{}) any {
				key := c.Draw(prop.SampledFrom(keysString...), "put.key")
				value := c.Draw(prop.Of[string](), "put.value")
				return []any{key, value}
			},
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Put", args, args[0])
				values, err := storePutCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
		{
			Name: "Get",
			Input: func(c *prop.Case, _ struct{}) any {
				key := c.Draw(prop.SampledFrom(keysString...), "get.key")
				return []any{key}
			},
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Get", args, args[0])
				values, err := storeGetCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
	}
}

// storePutCall calls Put on subject with the arguments args, and returns
// the values of the call beside its error.
func storePutCall(ctx context.Context, subject hosted.Store, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	a1, _ := args[1].(string)
	return nil, subject.Put(ctx, a0, a1)
}

// storeGetCall calls Get on subject with the arguments args, and returns
// the values of the call beside its error.
func storeGetCall(ctx context.Context, subject hosted.Store, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	r0, err := subject.Get(ctx, a0)
	return []any{r0}, err
}

// storeReference returns the function that applies an operation of a
// history to the reference r by the name of its callable.
func storeReference(r hosted.Store) func(context.Context, string, []any) conform.Output {
	return func(ctx context.Context, operation string, args []any) conform.Output {
		var values []any
		var err error
		switch operation {
		case "Put":
			values, err = storePutCall(ctx, r, args)
		case "Get":
			values, err = storeGetCall(ctx, r, args)
		}
		return conform.OutputOf(err, values...)
	}
}

// storeWorld is the world of the subject of Store, which the checks of its
// world probes run.
var storeWorld = probe.World[hosted.Store]{
	Operations: storeOperations,
	Reference:  storeReference,
	Clients:    3,
}

// storeOperations returns the operations of the world of Store in the case
// c, over the pools of the keys that c chooses.
func storeOperations(c *prop.Case) []probe.Operation[hosted.Store] {
	keysString := probe.NewPool(
		c,
		prop.List(prop.Of[string](), prop.Unique(), prop.MinSize(1), prop.MaxSize(3)),
		"keys.string",
	)
	return []probe.Operation[hosted.Store]{
		{
			Name: "Put",
			Input: func(c *prop.Case) any {
				key := keysString.Pick(c, "put.key")
				value := c.Draw(prop.Of[string](), "put.value")
				return []any{key, value}
			},
			Args: func(input any) []any {
				args, _ := input.([]any)
				return args
			},
			Keys: func(input any) []any {
				args, _ := input.([]any)
				return []any{args[0]}
			},
			Call: func(ctx context.Context, s hosted.Store, input any) (conform.Output, error) {
				args, _ := input.([]any)
				values, err := storePutCall(ctx, s, args)
				return conform.OutputOf(err, values...), err
			},
		},
		{
			Name: "Get",
			Input: func(c *prop.Case) any {
				key := keysString.Pick(c, "get.key")
				return []any{key}
			},
			Args: func(input any) []any {
				args, _ := input.([]any)
				return args
			},
			Keys: func(input any) []any {
				args, _ := input.([]any)
				return []any{args[0]}
			},
			Call: func(ctx context.Context, s hosted.Store, input any) (conform.Output, error) {
				args, _ := input.([]any)
				values, err := storeGetCall(ctx, s, args)
				return conform.OutputOf(err, values...), err
			},
		},
	}
}

